import { DOMAIN } from './actions'

export const INITIAL_STATE = {}

const reducer = (state, action) => {
  const { payload } = action

  switch (action.type) {
    case DOMAIN.GET_DOMAIN:
    case DOMAIN.ADD_DOMAIN:
    case DOMAIN.REMOVE_DOMAIN:
    case DOMAIN.IMPORT_DOMAIN:
    case DOMAIN.EXPORT_DOMAIN:
      return { ...state, ...payload }
    case DOMAIN.RESET_REDUX_STATE_DOMAIN:
      if (payload && Array.isArray(payload)) {
        const stateToBeReset = {}
        payload.forEach((key) => {
          stateToBeReset[key] = INITIAL_STATE[key]
        })
        return {
          ...state,
          ...stateToBeReset
        }
      } else {
        return {
          ...state
        }
      }
    default:
      return state
  }
}

export default reducer
