/* eslint-disable react-hooks/exhaustive-deps */
import React, { useState, useEffect, useCallback } from 'react'
import { notification } from 'antd'
import fileDownload from 'js-file-download'
import QueryString from 'query-string'

import {
  useLoaderContextValue,
  useErrorContextValue,
  resetError
} from '@pasarpolis/common-react-hooks'

import CommonTable from './domainTable'
import Modal from './addDomainModal'
import {
  useGetDomain,
  useAddDomain,
  useRemoveDomain,
  useResetState,
  useImportDomain,
  useExportDomain
} from '../state/hooks/useEmailDomainContext'

export const Domains = (props) => {
  const { domainType, title, location } = props
  const [{ getDomainData = {} }, getDomain] =
    useGetDomain()

  const [{ importDomainData = {} }, importDomain] =
    useImportDomain()
  const [{ exportDomainData = [] }, exportDomain] =
    useExportDomain()

  const [{ addDomainData }, addDomain] =
    useAddDomain()
  const [{ removeDomainData }, removeDomain] =
    useRemoveDomain()
  const [showAddModal, setAddModalValue] = useState(false)
  const [resetState] = useResetState()
  const [
    {
      GET_DOMAIN_LOADER,
      ADD_DOMAIN_LOADER,
      REMOVE_DOMAIN_LOADER,
      EXPORT_DOMAIN_LOADER,
      IMPORT_DOMAIN_LOADER
    }
  ] = useLoaderContextValue()

  const [
    {
      getDomainStatus,
      GET_DOMAIN_ERROR,
      addDomainStatus,
      ADD_DOMAIN_ERROR,
      removeDomainStatus,
      REMOVE_DOMAIN_ERROR,
      exportDomainStatus,
      EXPORT_DOMAIN_ERROR,
      addDomainErrorData,
      removeDomainErrorData,
      importDomainStatus,
      importDomainErrorData,
      IMPORT_DOMAIN_ERROR,
      exportDomainErrorData
    },
    dispatchError
  ] = useErrorContextValue()
  useEffect(() => {
    return () => resetState(['getDomainData'])
  }, [])

  const getTableData = useCallback(() => {
    const oldSearch = QueryString.parse(location?.search)
    getDomain({
      query: {
        ...oldSearch,
        domain_type: domainType,
        page: 1,
        page_size: 10
      }
    })
  }, [getDomain, domainType])

  // Error handling notify error status
  useEffect(() => {
    if (GET_DOMAIN_ERROR) {
      getDomainStatus &&
        notification.error({ message: getDomainStatus })
      dispatchError(
        resetError({
          GET_DOMAIN_ERROR: false,
          getDomainStatus: ''
        })
      )
    } else if (ADD_DOMAIN_ERROR) {
      addDomainErrorData?.message &&
        notification.error({ message: addDomainErrorData?.message })
      dispatchError(
        resetError({
          ADD_DOMAIN_ERROR: false,
          addDomainStatus: '',
          addDomainErrorData: ''
        })
      )
    } else if (
      !ADD_DOMAIN_ERROR &&
      addDomainStatus === 'success'
    ) {
      addDomainData?.message &&
        notification.success({ message: addDomainData?.message })
      dispatchError(
        resetError({
          addDomainStatus: ''
        })
      )
      setAddModalValue(false)
      getTableData()
    } else if (REMOVE_DOMAIN_ERROR) {
      removeDomainErrorData?.message &&
        notification.error({ message: removeDomainErrorData?.message })
      dispatchError(
        resetError({
          REMOVE_DOMAIN_ERROR: false,
          removeDomainStatus: '',
          removeDomainErrorData: ''
        })
      )
    } else if (
      !REMOVE_DOMAIN_ERROR &&
      removeDomainStatus === 'success'
    ) {
      removeDomainData?.message &&
        notification.success({ message: removeDomainData?.message })
      dispatchError(
        resetError({
          removeDomainStatus: ''
        })
      )
      getTableData()
    } else if (EXPORT_DOMAIN_ERROR) {
      exportDomainErrorData?.message &&
        notification.error({ message: exportDomainErrorData?.message })
      dispatchError(
        resetError({
          EXPORT_DOMAIN_ERROR: false,
          exportDomainStatus: ''
        })
      )
    } else if (
      !EXPORT_DOMAIN_ERROR &&
      exportDomainStatus === 'success'
    ) {
      exportDomainData?.message &&
        notification.success({
          message: exportDomainData?.message
        })
      dispatchError(
        resetError({
          exportDomainStatus: ''
        })
      )
      fileDownload(
        JSON.stringify(exportDomainData?.data),
        `${domainType}Domain.json`
      )
    } else if (IMPORT_DOMAIN_ERROR) {
      importDomainErrorData?.message &&
        notification.error({
          message: importDomainErrorData?.message
        })
      dispatchError(
        resetError({
          IMPORT_DOMAIN_ERROR: false,
          importDomainStatus: ''
        })
      )
    } else if (
      !IMPORT_DOMAIN_ERROR &&
      importDomainStatus === 'success'
    ) {
      importDomainData?.message &&
        notification.success({
          message: importDomainData?.message
        })
      getTableData()
      dispatchError(
        resetError({
          importDomainStatus: ''
        })
      )
    }
  }, [
    GET_DOMAIN_ERROR,
    ADD_DOMAIN_ERROR,
    addDomainErrorData,
    addDomainData,
    REMOVE_DOMAIN_ERROR,
    EXPORT_DOMAIN_ERROR,
    removeDomainData,
    exportDomainData,
    exportDomainStatus,
    removeDomainStatus,
    addDomainStatus,
    getDomainStatus,
    removeDomainErrorData,
    importDomainStatus,
    importDomainErrorData,
    IMPORT_DOMAIN_ERROR,
    importDomainData,
    exportDomainErrorData
  ])

  return (
    <>
      {showAddModal && (
        <Modal
          show={showAddModal}
          toggleAddModal={setAddModalValue}
          addDomain={addDomain}
          loading={!!ADD_DOMAIN_LOADER}
          domainType={domainType}
        />
      )}
      <CommonTable
        tableData={getDomainData}
        getTabledataRequest={getDomain}
        toggleAddModal={setAddModalValue}
        loader={
          !!(
            GET_DOMAIN_LOADER ||
            REMOVE_DOMAIN_LOADER ||
            EXPORT_DOMAIN_LOADER
          )
        }
        title={title}
        removeDomain={removeDomain}
        importDomain={importDomain}
        exportDomain={exportDomain}
        importingFileLoader={!!IMPORT_DOMAIN_LOADER}
        domainType={domainType}
        {...props}
      />
    </>
  )
}

export default Domains
