import { Modal, Form, Row, Input, Button, notification } from 'antd'
import React, { useCallback } from 'react'

import { ModalWrapper } from './style'
import { emailDomainRegExp } from '../../../../constants/validation-regex'

const FormItem = Form.Item
const AddRecipientModal = ({
  form,
  show,
  toggleAddModal,
  addDomain,
  loading,
  domainType
}) => {
  const { getFieldDecorator } = form

  const validateForm = useCallback(async () => {
    return new Promise((resolve) => {
      form.validateFields((error, values) => {
        resolve(!error)
      })
    })
  }, [form])

  const onSubmit = useCallback(
    async (e) => {
      e.preventDefault()
      const values = form.getFieldsValue()
      const valid = await validateForm()
      if (valid) {
        if (values.domain_name === 'pasarpolis.com') {
          notification.error({ message: 'Action on reserved domain cannot be taken' })
          return
        }
        addDomain({
          query: { domain_type: domainType },
          body: {
            domain_name: values.domain_name
          }
        })
      }
    },
    [form, addDomain, domainType, validateForm]
  )
  return (
    <Modal
      visible={show}
      okText='Save'
      onCancel={() => toggleAddModal(false)}
      title='Add Domain'
      maskClosable={false}
      width='50%'
      footer={null}
    >
      <ModalWrapper>
        <Form onSubmit={onSubmit}>
          <Row type='flex' align='middle' className='row'>
            <h4 className='label'>
              <b>Domain : </b>
            </h4>
            <FormItem className='form-item'>
              {getFieldDecorator('domain_name', {
                rules: [
                  {
                    required: true,
                    pattern: emailDomainRegExp,
                    message: 'Please enter valid domain'
                  }
                ]
              })(<Input placeholder='Domain' />)}
            </FormItem>
          </Row>
          <Row type='flex' justify='end'>
            <Button type='primary button' onClick={() => toggleAddModal(false)}>
              Cancel
            </Button>
            <Button type='primary button' htmlType='submit' loading={loading}>
              Save
            </Button>
          </Row>
        </Form>
      </ModalWrapper>
    </Modal>
  )
}

export default Form.create({})(AddRecipientModal)
