import React, { createContext, useContext, useReducer } from 'react'
import reducer, { INITIAL_STATE } from '../state/reducer'

export const DomainContext = createContext()

export const DomainContextProvider = (props) => {
  return (
    <DomainContext.Provider value={useReducer(reducer, INITIAL_STATE)}>
      {props.children}
    </DomainContext.Provider>
  )
}

export const useDomainContextValue = () => useContext(DomainContext)
