import { useServiceRequest } from '@pasarpolis/common-react-hooks'

import { useDomainContextValue } from '../../context'
import { DOMAIN } from '../actions'

export const useDomainServiceCall = (actionsCall = () => {}) => {
  const [domainState, dispatch] = useDomainContextValue()
  const [callApi] = useServiceRequest(dispatch)
  const request = async (payload = {}) => {
    await callApi(actionsCall({
      ...payload
    }))
  }

  return [domainState, request]
}

export const useGetDomain = () => {
  return useDomainServiceCall(DOMAIN.getDomain)
}

export const useAddDomain = () => {
  return useDomainServiceCall(DOMAIN.addDomain)
}

export const useRemoveDomain = () => {
  return useDomainServiceCall(DOMAIN.removeDomain)
}

export const useImportDomain = () => {
  return useDomainServiceCall(DOMAIN.importDomain)
}

export const useExportDomain = () => {
  return useDomainServiceCall(DOMAIN.exportDomain)
}

export const useResetState = () => {
  const [, dispatch] = useDomainContextValue()
  const resetState = (keys = []) => {
    dispatch(DOMAIN.resetReduxStateDomain(keys))
  }
  return [resetState]
}
