import urls from '../../../../config/urls'
const configUrl = urls.url

export const DOMAIN = {
  GET_DOMAIN: 'GET_DOMAIN',
  GET_DOMAIN_REQUEST: 'GET_DOMAIN_REQUEST',

  ADD_DOMAIN: 'ADD_DOMAIN',
  ADD_DOMAIN_REQUEST: 'ADD_DOMAIN_REQUEST',

  REMOVE_DOMAIN: 'REMOVE_DOMAIN',
  REMOVE_DOMAIN_REQUEST: 'REMOVE_DOMAIN_REQUEST',

  IMPORT_DOMAIN: 'IMPORT_DOMAIN',
  IMPORT_DOMAIN_REQUEST: 'IMPORT_DOMAIN_REQUEST',

  EXPORT_DOMAIN: 'EXPORT_DOMAIN',
  EXPORT_DOMAIN_REQUEST: 'EXPORT_DOMAIN_REQUEST',

  RESET_REDUX_STATE_DOMAIN: 'RESET_REDUX_STATE_DOMAIN',

  getDomain: payload => ({
    type: DOMAIN.GET_DOMAIN_REQUEST,
    payload: {
      ...payload,
      method: 'get',
      url: configUrl.getDomainApi
    }
  }),
  addDomain: payload => ({
    type: DOMAIN.ADD_DOMAIN_REQUEST,
    payload: {
      ...payload,
      method: 'post',
      url: configUrl.addDomainApi
    }
  }),
  removeDomain: payload => ({
    type: DOMAIN.REMOVE_DOMAIN_REQUEST,
    payload: {
      ...payload,
      method: 'delete',
      url: configUrl.removeDomainApi
    }
  }),
  importDomain: payload => ({
    type: DOMAIN.IMPORT_DOMAIN_REQUEST,
    payload: {
      ...payload,
      method: 'post',
      url: configUrl.importDomainApi
    }
  }),
  exportDomain: payload => ({
    type: DOMAIN.EXPORT_DOMAIN_REQUEST,
    payload: {
      ...payload,
      method: 'get',
      url: configUrl.exportDomainApi
    }
  }),
  resetReduxStateDomain: keys => ({
    type: DOMAIN.RESET_REDUX_STATE_DOMAIN,
    payload: keys
  })
}
